55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	};
62	
63	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
64	
65	const quote = (step: QuoteStep): QuoteResult => {
66	  const policyBase = step.items.reduce((sum, item) => sum + basePremiumOf(item), 0);
67	  const total =
68	    policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
69	  return { premium: Math.ceil(total) };
70	};
71	
72	export const runScenario = (scenario: Scenario): ScenarioOutput => {
73	  return { results: scenario.steps.map((step) => quote(step as QuoteStep)) };
74	};
